static int isvowel(char c)
{
  switch (c)
  {
    case 'A': case 'E': case 'I': case 'O': case 'U':
    case 'a': case 'e': case 'i': case 'o': case 'u': return 1;
    default: return 0;
  }
}

static int can_activate_basic_equipment_impl(int player, int card, event_t event,
                                              int equip_cost, target_definition_t *td)
{
  int cl[6] = {0};
  cl[((unsigned int)equip_cost >> 8) & 0xff] = ((unsigned int)equip_cost >> 16) & 0xff;
  if (can_sorcery_be_played(player, event) && !is_what(player, card, TYPE_CREATURE) &&
      can_use_activated_abilities(player, card))
  {
    int cost = get_updated_equip_cost(player, card, equip_cost & 0xff);
    if (has_mana_for_activated_ability(player, card, cost, cl[1], cl[2], cl[3], cl[4], cl[5]))
      return check_for_equipment_targets_impl(player, card, td);
  }
  return 0;
}

static int check_multisubtype_by_csvid(int csvid, int sub1, int sub2, int sub3, int sub4, int sub5)
{
  return (sub1 > 0 && has_subtype_by_id(-1, csvid, sub1)) ||
         (sub2 > 0 && has_subtype_by_id(-1, csvid, sub2)) ||
         (sub3 > 0 && has_subtype_by_id(-1, csvid, sub3)) ||
         (sub4 > 0 && has_subtype_by_id(-1, csvid, sub4)) ||
         (sub5 > 0 && has_subtype_by_id(-1, csvid, sub5));
}

static int check_multisubtype_all_by_csvid(int csvid, int sub1, int sub2, int sub3, int sub4, int sub5)
{
  return (sub1 <= 0 || has_subtype_by_id(-1, csvid, sub1)) &&
         (sub2 <= 0 || has_subtype_by_id(-1, csvid, sub2)) &&
         (sub3 <= 0 || has_subtype_by_id(-1, csvid, sub3)) &&
         (sub4 <= 0 || has_subtype_by_id(-1, csvid, sub4)) &&
         (sub5 <= 0 || has_subtype_by_id(-1, csvid, sub5));
}

static void fabricate(int player, int card, int amount, int priority_counters, int priority_servo)
{
  char counters[100], servo[100];
  scnprintf(counters, 100, "Add %d +1/+1 counters", amount);
  scnprintf(servo, 100, "Create %d Servo", amount);
  int choice = dialog_impl(player, card, EVENT_CAST_SPELL, "\001\014", "\001\003",
                           counters, 1, priority_counters, servo, 1, priority_servo, 0, 0, 0, 0);
  if (choice == 1)
    add_counters(player, card, player, card, COUNTER_P1_P1, amount);
  else if (choice == 2)
    generate_tokens_by_id(player, card, CARD_ID_SERVO, amount);
}

static int eot_flipper(int player, int card, event_t event)
{
  card_instance_t *instance = get_card_instance(player, card);
  double_faced_card(player, card, event);
  arcane_spirit_spell_trigger(player, card, event, duh_mode(player) ? 2 : 1);
  if (event == EVENT_SPA)
    add_counters(player, card, player, card, COUNTER_KI, 1);
  if (count_counters(player, card, COUNTER_KI) > 1 && trigger_condition == TRIGGER_EOT &&
      card == affected_card && player == affected_card_controller && player == reason_for_trigger_controller)
  {
    if (event == EVENT_TRIGGER)
      event_result |= player + 1;
    else if (event == EVENT_RESOLVE_TRIGGER)
    {
      true_transform(player, card);
      verify_legend_rule(player, card, instance->targets[13].card);
    }
  }
  return 0;
}

static void activate_ruins_of_oran_rief(int player, int card, int color)
{
  for (int p = 0; p < 2; ++p)
    for (int c = active_cards_count[p] - 1; c >= 0; --c)
    {
      card_instance_t *instance = get_card_instance(player, card);
      if (in_play(p, c) && is_what(p, c, TYPE_CREATURE) && check_special_flags(p, c, 0x1000))
      {
        unsigned int target_color = get_color(instance->targets[0].player, instance->targets[0].card);
        if (color == COLOR_TEST_COLORLESS ? !(target_color & COLOR_TEST_ANY_COLORED) : (target_color & color) != 0)
          add_counters(player, card, instance->targets[0].player, instance->targets[0].card, COUNTER_P1_P1, 1);
      }
    }
}

static void ghireds_special_populate(int player, int card)
{
  target_t target;
  if (player == AI || ai_is_speculating == 1)
  {
    test_definition_t test;
    default_test_definition(&test, TYPE_CREATURE);
    test.type_flag = F1_IS_TOKEN;
    target.card = check_battlefield_for_special_card(player, card, player, 1, &test);
    target.player = player;
    if (target.card < 0)
      return;
  }
  else
  {
    target_definition_t td;
    base_target_definition(player, card, &td, TYPE_CREATURE);
    td.allowed_controller = td.preferred_controller = player;
    td.allow_cancel = 0;
    td.special = TARGET_SPECIAL_EXTRA_FUNCTION;
    td.extra = (int32_t)target_is_token_too;
    if (!can_target(&td) || !select_target(player, card - 1000, &td,
                                          "Select a creature token you control.", &target))
      return;
  }
  token_generation_t token;
  copy_token_definition(player, card, &token, target.player, target.card);
  token.action = TOKEN_ACTION_ATTACKING;
  generate_token(&token);
}

static int whenever_a_treasure_is_sacrificed(int player, int card, event_t event,
                                               int t_player, int trig_mode)
{
  if (event == EVENT_GRAVEYARD_FROM_PLAY && in_play(affected_card_controller, affected_card) &&
      get_card_instance(affected_card_controller, affected_card)->kill_code == KILL_SACRIFICE &&
      get_id(affected_card_controller, affected_card) == CARD_ID_TREASURE &&
      !check_special_flags(affected_card_controller, affected_card, 0x800))
    count_for_gfp_ability(player, card, event, t_player, 0x47, NULL);
  return resolve_gfp_ability(player, card, event, trig_mode);
}

static int reveal_top_library_type_cards_put_in_hand_rest_bottom_library_any_order(int player, int card,
                                                                                     int type, int cards_to_look)
{
  int *deck = deck_ptr[player];
  show_deck(current_turn, deck, cards_to_look, "Here's the revealed cards", 0, ENGINE_DONE_LABEL);
  show_deck(current_turn ^ 1, deck, cards_to_look, "Here's the revealed cards", 0, ENGINE_DONE_LABEL);
  int amount = MIN(cards_to_look, count_deck(player));
  for (int pos = amount - 1; pos >= 0; --pos)
    if (is_what(-1, deck[pos], type))
    {
      add_card_to_hand(player, deck[pos]);
      remove_card_from_deck(player, pos);
      --amount;
    }
  if (amount > 0)
    put_top_x_on_bottom(player, player, amount);
  return 0;
}

static int each_player_reveal_top_library_type_cards_put_in_play_exile_rest(int player, int card,
                                                                            int type, int cards_to_look)
{
  for (int phase = 0; phase < 2; ++phase)
  {
    int p = phase ^ current_turn;
    if (deck_ptr[p][0] == -1)
      continue;
    show_deck(p, deck_ptr[p], cards_to_look, "Here are the revealed cards from controller's deck.", 0, ENGINE_DONE_LABEL);
    show_deck(1 - p, deck_ptr[p], cards_to_look, "Here are the revealed cards from controller's opponent's deck.", 0, ENGINE_DONE_LABEL);
    int count = count_deck(p);
    int amount = MIN(cards_to_look, count);
    if (count < 1)
      break;
    int *deck = deck_ptr[p];
    for (int pos = amount - 1; pos >= 0; --pos)
      if (is_what(-1, deck[pos], type))
      {
        int added = add_card_to_hand(p, deck[pos]);
        put_into_play(p, added);
        add_state(p, added, STATE_TAPPED);
        remove_card_from_deck(p, pos);
        --amount;
      }
    if (amount > 0)
      rfg_top_n_cards_of_deck(p, amount);
  }
  return 0;
}

static int generic_aura_impl(int player, int card, event_t event, target_definition_t *td,
                               char *prompt, int p_plus, int t_plus, int k_plus, int k_special,
                               int subtype, int clr, int flags)
{
  pump_ability_t ability;
  default_pump_ability_definition(player, card, &ability, p_plus, t_plus, k_plus, k_special);
  ability.subtype = subtype;
  ability.color = clr;
  if (flags & 8) ability.paue_flags |= 0x80000;
  if (flags & 16) ability.paue_flags |= 0x40000;
  if (flags & 32) ability.paue_flags |= 0x20000;
  if (flags & 1) ability.disabling_mode |= 0x28;
  if (flags & 2) ability.disabling_mode |= 0x7e;
  if (flags & 4) ability.disabling_mode |= 0x38;
  pump_attached(player, card, event, &ability);
  return aura(player, card, event, td, prompt);
}

static int compare_iid_token(iid_t int_id, token_generation_t *token)
{
  if (token->id != cards_data[int_id].id ||
      (token->pow >= 0 && token->pow != cards_data[int_id].power) ||
      (token->tou >= 0 && token->tou != cards_data[int_id].toughness) ||
      !(cards_data[int_id].static_ability & token->key_plus))
    return 0;
  int artifact_matches = !(token->action & TOKEN_ACTION_CONVERT_INTO_ARTIFACT) ||
                          (cards_data[int_id].type & TYPE_ARTIFACT);
  unsigned int color = token->color_forced ? token->color_forced : cards_data[int_id].color;
  if (token->s_player >= 0 && token->s_card >= 0 && !token->no_sleight)
    color = get_sleighted_color_test(token->s_player, token->s_card, color & COLOR_TEST_ANY_COLORED);
  return cards_data[int_id].color == color && artifact_matches;
}

static int count_party_guts(int num_candidates, int *candidates_by_class)
{
  InitNumberBitsSet();
  for (int bits = 0; bits < 16; ++bits)
    if (candidates_by_class[bits] > number_bits_set[bits])
    {
      num_candidates -= candidates_by_class[bits] - number_bits_set[bits];
      candidates_by_class[bits] = number_bits_set[bits];
    }
  for (int first = 1; first <= 4; first *= 2)
    for (int second = first * 2; second <= 8; second *= 2)
      if (candidates_by_class[first] && candidates_by_class[second])
      {
        num_candidates -= candidates_by_class[first | second];
        candidates_by_class[first | second] = 0;
      }
      else if (candidates_by_class[first | second] >= 2)
      {
        num_candidates -= candidates_by_class[first] + candidates_by_class[second];
        candidates_by_class[first] = candidates_by_class[second] = 0;
      }
  int available = 0;
  for (int bits = 0; bits < 16; ++bits)
    if (candidates_by_class[bits])
      available |= bits;
  return MIN(num_candidates, number_bits_set[available]);
}

static void cmc_mod_for_spectacle(int player, int card, event_t event, int colorless,
                                  int black, int blue, int green, int red, int white)
{
  if (event == EVENT_MODIFY_COST)
  {
    card_instance_t *instance = get_card_instance(player, card);
    int cost = get_updated_casting_cost(player, card, -1, EVENT_MODIFY_COST, colorless);
    if (has_mana_multi(player, cost, black, blue, green, red, white) &&
        get_trap_condition(1 - player, TRAP_LIFE_LOST))
    {
      instance->info_slot = 1;
      null_casting_cost(player, card);
    }
    else
      instance->info_slot = 0;
  }
}

static int has_misc_protection_from(int protected_player, int protected_card, int from_player,
                                    int from_card, is_protected_from_mode_t new_protection_mode,
                                    int allow_granted_protection)
{
  uint32_t initial = (uint32_t)new_protection_mode << 24;
  if (protected_card < 0)
  {
    if (!(player_bits[protected_player] & PB_PROTECTION))
      return 0;
  }
  else
  {
    uint32_t flags = get_card_instance(protected_player, protected_card)->ext->sp_keywords2;
    int granted = allow_granted_protection && (flags & SP_KEYWORD2_GRANTED_PROT_MISC);
    if (!(flags & SP_KEYWORD2_PROT_MISC) &&
        (!(flags & 4) || new_protection_mode != IPF_TARGET || from_player == protected_player) && !granted)
      return 0;
    if (!granted)
    {
      if (is_humiliated(protected_player, protected_card, AL_STATIC))
        return 0;
      return dispatch_event_arbitrary_to_one_card_with_initial_event_result(
          protected_player, protected_card, EVENT_PROT_MISC, protected_player, protected_card,
          from_player, from_card, (int)initial) & 0xffffff;
    }
  }
  return dispatch_event_with_attacker_and_initial_event_result(
      protected_player, protected_card, EVENT_PROT_MISC, from_player, from_card, (int)initial) & 0xffffff;
}

